#!/usr/bin/env python3
"""
创建 Teambition 任务
用法: uv run scripts/create_task.py --title <标题> [选项]

时区说明: 日期参数请传入东八区时间，脚本自动转换为 UTC（减 8 小时）。
优先级: 0=紧急 1=高 2=中 3=低
"""

import json
import sys
from datetime import datetime, timezone, timedelta
from typing import Any, Dict, Optional

import call_api

CST = timezone(timedelta(hours=8))

def cst_to_utc(dt_str: str) -> str:
    """将东八区 ISO 字符串转换为 UTC ISO 字符串。若已含 Z/+00:00 则原样返回。"""
    if dt_str.endswith("Z") or "+00:00" in dt_str:
        return dt_str
    # 尝试解析为 naive datetime，视为 CST
    for fmt in ("%Y-%m-%dT%H:%M:%S.%f", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d"):
        try:
            dt = datetime.strptime(dt_str, fmt)
            dt_cst = dt.replace(tzinfo=CST)
            dt_utc = dt_cst.astimezone(timezone.utc)
            return dt_utc.strftime("%Y-%m-%dT%H:%M:%S.000Z")
        except ValueError:
            continue
    # 无法解析，原样返回
    return dt_str

def create_task(task_data: Dict[str, Any]) -> None:
    payload: Dict[str, Any] = {"content": task_data["content"]}

    optional = [
        "projectId", "executorId", "involveMembers", "taskflowstatusId",
        "startDate", "dueDate", "note", "priority", "parentTaskId",
        "progress", "visible", "storyPoint", "scenariofieldconfigId", "customfields",
    ]
    for field in optional:
        if field in task_data and task_data[field] is not None:
            payload[field] = task_data[field]

    data = call_api.post("v3/task/create", payload)
    task = data.get("result", data)
    print(json.dumps(task, ensure_ascii=False, indent=2))

def main() -> None:
    if "--help" in sys.argv:
        print("""用法: uv run scripts/create_task.py --title <标题> [选项]

必需:
  --title <标题>                任务标题

可选:
  --project-id <ID>             项目 ID（先用 query_projects.py 按名称查询）
  --executor-id <ID>            执行人 ID（先用 query_members.py 按姓名查询）
  --involve-members <JSON>      参与者 ID 列表，JSON 数组
  --taskflowstatus-id <ID>      任务状态 ID（先用 get_taskflow_statuses.py 查询）
  --start-date <日期>           开始日期（东八区，自动转 UTC）
  --due-date <日期>             截止日期（东八区，自动转 UTC）
  --note <备注>                 任务备注
  --priority <0-3>              优先级（0=紧急 1=高 2=中 3=低）
  --parent-task-id <ID>         父任务 ID（创建子任务）
  --progress <0-100>            进度百分比
  --visible <类型>              可见性（involves=仅参与者 members=项目成员）
  --story-point <点数>          故事点
  --scenariofieldconfig-id <ID> 任务类型 ID
  --customfields <JSON>         自定义字段，JSON 数组
  --help                        显示帮助

示例:
  uv run scripts/create_task.py \\
    --project-id 'xxx' --title '完成需求文档'

  uv run scripts/create_task.py \\
    --project-id 'xxx' --title '实现登录模块' \\
    --executor-id 'uid' --due-date '2026-04-01' --priority 1""")
        sys.exit(0)

    task_data: Dict[str, Any] = {}
    i = 1
    while i < len(sys.argv):
        arg = sys.argv[i]
        if arg == "--title" and i + 1 < len(sys.argv):
            task_data["content"] = sys.argv[i + 1]; i += 2
        elif arg == "--project-id" and i + 1 < len(sys.argv):
            task_data["projectId"] = sys.argv[i + 1]; i += 2
        elif arg == "--executor-id" and i + 1 < len(sys.argv):
            task_data["executorId"] = sys.argv[i + 1]; i += 2
        elif arg == "--involve-members" and i + 1 < len(sys.argv):
            task_data["involveMembers"] = json.loads(sys.argv[i + 1]); i += 2
        elif arg == "--taskflowstatus-id" and i + 1 < len(sys.argv):
            task_data["taskflowstatusId"] = sys.argv[i + 1]; i += 2
        elif arg == "--start-date" and i + 1 < len(sys.argv):
            task_data["startDate"] = cst_to_utc(sys.argv[i + 1]); i += 2
        elif arg == "--due-date" and i + 1 < len(sys.argv):
            task_data["dueDate"] = cst_to_utc(sys.argv[i + 1]); i += 2
        elif arg == "--note" and i + 1 < len(sys.argv):
            task_data["note"] = sys.argv[i + 1]; i += 2
        elif arg == "--priority" and i + 1 < len(sys.argv):
            task_data["priority"] = int(sys.argv[i + 1]); i += 2
        elif arg == "--parent-task-id" and i + 1 < len(sys.argv):
            task_data["parentTaskId"] = sys.argv[i + 1]; i += 2
        elif arg == "--progress" and i + 1 < len(sys.argv):
            task_data["progress"] = int(sys.argv[i + 1]); i += 2
        elif arg == "--visible" and i + 1 < len(sys.argv):
            task_data["visible"] = sys.argv[i + 1]; i += 2
        elif arg == "--story-point" and i + 1 < len(sys.argv):
            task_data["storyPoint"] = sys.argv[i + 1]; i += 2
        elif arg == "--scenariofieldconfig-id" and i + 1 < len(sys.argv):
            task_data["scenariofieldconfigId"] = sys.argv[i + 1]; i += 2
        elif arg == "--customfields" and i + 1 < len(sys.argv):
            task_data["customfields"] = json.loads(sys.argv[i + 1]); i += 2
        else:
            print(f"❌ 未知参数: {arg}", file=sys.stderr); sys.exit(1)

    if "content" not in task_data:
        print("❌ 缺少必需参数 --title", file=sys.stderr); sys.exit(1)

    create_task(task_data)

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
查询 Teambition 任务详情（支持逗号分隔批量查询）
用法: uv run scripts/query_task_detail.py <taskId[,taskId,...]> [--detail-level simple|detailed] [--extra-fields f1,f2]
"""

import json
import sys
from typing import Any, Dict, List, Optional

import call_api

# 系统默认优先级名称（兜底值，企业未配置时使用）
DEFAULT_PRIORITY_LABEL = {0: "紧急", 1: "高", 2: "中", 3: "低"}

# 缓存优先级配置
_priority_label_cache: Optional[Dict[int, str]] = None

def get_priority_label_map() -> Dict[int, str]:
    """
    获取优先级名称映射。
    直接查询优先级配置，无需 organizationId。
    失败时静默返回默认映射，不中断主流程。
    """
    global _priority_label_cache
    if _priority_label_cache is not None:
        return _priority_label_cache

    try:
        resp = call_api.get("v3/project/priority/list")
        priorities = resp.get("result", [])
        if priorities:
            label_map = {int(p["priority"]): p["name"] for p in priorities if "priority" in p and "name" in p}
            _priority_label_cache = label_map
            return label_map
    except Exception:
        pass

    return DEFAULT_PRIORITY_LABEL

# 文件下载链接有效期：7天（604800秒），API支持的最长有效期
FILE_URL_EXPIRE_SECONDS = 604800

SIMPLE_FIELDS = {"id", "content", "isDone", "executorId", "projectId", "dueDate", "priority", "created", "updated", "note"}

def format_simple(task: Dict[str, Any], extra_fields: Optional[List[str]] = None) -> Dict[str, Any]:
    result = {k: task.get(k) for k in SIMPLE_FIELDS}
    if extra_fields:
        for f in extra_fields:
            result[f] = task.get(f)
    p = result.get("priority")
    if p is not None:
        label_map = get_priority_label_map()
        result["priorityLabel"] = label_map.get(p, str(p))
    return result


def _extract_resource_id(meta_string: Optional[str]) -> Optional[str]:
    """从 metaString 中解析 resourceId"""
    if not meta_string:
        return None
    try:
        meta = json.loads(meta_string)
        return meta.get("resourceId")
    except json.JSONDecodeError:
        return None


def enrich_file_custom_fields(task: Dict[str, Any]) -> None:
    """
    为文件类型的自定义字段补齐下载链接。
    仅在 detailed 模式下调用。
    """
    customfields = task.get("customfields", [])
    if not customfields:
        return

    # 收集所有文件类型的 resourceId
    resource_ids = []
    file_entries = []  # 记录 (cf_index, value_index, entry) 用于回填

    for cf_idx, cf in enumerate(customfields):
        if cf.get("type") != "work":
            continue
        value = cf.get("value", [])
        if not isinstance(value, list):
            continue
        for val_idx, entry in enumerate(value):
            if not isinstance(entry, dict):
                continue
            resource_id = _extract_resource_id(entry.get("metaString"))
            if resource_id:
                resource_ids.append(resource_id)
                file_entries.append((cf_idx, val_idx, entry, resource_id))

    if not resource_ids:
        return

    # 批量查询文件详情
    try:
        resp = call_api.post(
            "v3/file/query/by-resource-ids",
            body={
                "needSign": True,
                "resourceIds": resource_ids,
                "expireAfterSeconds": FILE_URL_EXPIRE_SECONDS,
            },
            headers={"X-Canary": "prepub"}
        )
        file_details = {f.get("resourceId"): f for f in resp.get(
            "result", []) if f.get("resourceId")}
    except Exception:
        # 查询失败时静默处理，不中断主流程
        return

    # 回填 downloadUrl
    for cf_idx, val_idx, entry, resource_id in file_entries:
        detail = file_details.get(resource_id)
        if detail and detail.get("downloadUrl"):
            entry["downloadUrl"] = detail["downloadUrl"]


# 缓存项目自定义字段配置，避免重复请求
_custom_field_cache: Dict[str, Dict[str, str]] = {}


def enrich_custom_field_names(task: Dict[str, Any]) -> None:
    """
    为自定义字段补齐字段名称（cfName）。
    根据 projectId 获取项目自定义字段配置，构建 cfId -> name 映射。
    """
    customfields = task.get("customfields", [])
    if not customfields:
        return

    project_id = task.get("projectId")
    if not project_id:
        return

    # 检查缓存
    if project_id not in _custom_field_cache:
        try:
            resp = call_api.get(
                f"v3/project/{project_id}/customfield/search")
            fields = resp.get("result", [])
            # 构建 cfId -> name 映射（尝试 id 和 _id 两个字段）
            _custom_field_cache[project_id] = {}
            for f in fields:
                cf_id = f.get("id") or f.get("_id")
                if cf_id:
                    _custom_field_cache[project_id][cf_id] = f.get("name")
        except Exception:
            # 查询失败时静默处理，不中断主流程
            return

    name_map = _custom_field_cache.get(project_id, {})
    if not name_map:
        return

    # 为每个自定义字段添加 cfName
    for cf in customfields:
        cf_id = cf.get("cfId")
        if cf_id and cf_id in name_map:
            cf["cfName"] = name_map[cf_id]


def query_task_detail(
    task_ids: str,
    detail_level: str = "detailed",
    extra_fields: Optional[List[str]] = None,
) -> None:
    data = call_api.get("v3/task/query", params={"taskId": task_ids})
    tasks: List[Dict[str, Any]] = data.get("result", [])

    if not tasks:
        print(json.dumps([], ensure_ascii=False, indent=2))
        return

    if detail_level == "simple":
        tasks = [format_simple(t, extra_fields) for t in tasks]
    else:
        # detailed: 补充 priorityLabel（自动获取企业优先级配置）
        for t in tasks:
            p = t.get("priority")
            if p is not None:
                label_map = get_priority_label_map()
                t["priorityLabel"] = label_map.get(p, str(p))
            # 为文件类型的自定义字段补齐下载链接
            enrich_file_custom_fields(t)
            # 为自定义字段补齐字段名称
            enrich_custom_field_names(t)

    print(json.dumps(tasks, ensure_ascii=False, indent=2))


def main() -> None:
    if len(sys.argv) < 2 or "--help" in sys.argv:
        print("""用法: uv run scripts/query_task_detail.py <taskId[,taskId,...]> [选项]

参数:
  taskId               任务 ID，多个用逗号分隔（批量查询，无需多次调用）

选项:
  --detail-level       detailed（默认）或 simple
  --extra-fields       简单模式下额外字段，逗号分隔（如 note,sprintId）
  --help               显示帮助

示例:
  uv run scripts/query_task_detail.py 67ec9b8c3c6130ac88605c3e
  uv run scripts/query_task_detail.py id1,id2,id3
  uv run scripts/query_task_detail.py id1 --detail-level detailed
  uv run scripts/query_task_detail.py id1 --extra-fields note,stageId""")
        sys.exit(0 if "--help" in sys.argv else 1)

    task_ids = sys.argv[1]
    detail_level = "detailed"
    extra_fields: Optional[List[str]] = None

    i = 2
    while i < len(sys.argv):
        arg = sys.argv[i]
        if arg == "--detail-level" and i + 1 < len(sys.argv):
            detail_level = sys.argv[i + 1]; i += 2
        elif arg == "--extra-fields" and i + 1 < len(sys.argv):
            extra_fields = [f.strip() for f in sys.argv[i + 1].split(",")]; i += 2
        else:
            print(f"❌ 未知参数: {arg}", file=sys.stderr)
            sys.exit(1)

    query_task_detail(task_ids, detail_level, extra_fields)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
查询 Teambition 任务列表（TQL）
用法: uv run scripts/query_tasks.py [--tql <TQL>] [--page-size N] [--page-token T] [--no-details]
"""

import json
import sys
from typing import Any, Dict, List, Optional

import call_api

# 系统默认优先级名称（兜底值，企业未配置时使用）
DEFAULT_PRIORITY_LABEL = {0: "紧急", 1: "高", 2: "中", 3: "低"}

# 缓存企业优先级配置，key 为 organizationId
_priority_label_cache: Dict[str, Dict[int, str]] = {}

# 文件下载链接有效期：7天（604800秒），API支持的最长有效期
FILE_URL_EXPIRE_SECONDS = 604800

# 默认请求的额外字段。
# v3/task/query 接口默认已返回：id、content、isDone、executorId、projectId、
# dueDate、priority、created、updated 等核心字段。
# 以下字段需要通过 fields 参数额外请求：
DEFAULT_EXTRA_FIELDS = [
    "note",        # 备注
    "sprintId",    # 所属迭代 ID
    "stageId",     # 所属任务列 ID
    "startDate",   # 开始时间
    "progress",    # 进度（0-100）
    "parentTaskId", # 父任务 ID（子任务场景）
]

def _extract_resource_id(meta_string: Optional[str]) -> Optional[str]:
    """从 metaString 中解析 resourceId"""
    if not meta_string:
        return None
    try:
        meta = json.loads(meta_string)
        return meta.get("resourceId")
    except json.JSONDecodeError:
        return None

def enrich_file_custom_fields(task: Dict[str, Any]) -> None:
    """
    为文件类型的自定义字段补齐下载链接。
    """
    customfields = task.get("customfields", [])
    if not customfields:
        return

    # 收集所有文件类型的 resourceId
    resource_ids = []
    file_entries = []  # 记录 (cf_index, value_index, entry) 用于回填

    for cf_idx, cf in enumerate(customfields):
        if cf.get("type") != "work":
            continue
        value = cf.get("value", [])
        if not isinstance(value, list):
            continue
        for val_idx, entry in enumerate(value):
            if not isinstance(entry, dict):
                continue
            resource_id = _extract_resource_id(entry.get("metaString"))
            if resource_id:
                resource_ids.append(resource_id)
                file_entries.append((cf_idx, val_idx, entry, resource_id))

    if not resource_ids:
        return

    # 批量查询文件详情
    try:
        resp = call_api.post(
            "v3/file/query/by-resource-ids",
            body={
                "needSign": True,
                "resourceIds": resource_ids,
                "expireAfterSeconds": FILE_URL_EXPIRE_SECONDS,
            },
            headers={"X-Canary": "prepub"}
        )
        file_details = {f.get("resourceId"): f for f in resp.get(
            "result", []) if f.get("resourceId")}
    except Exception:
        # 查询失败时静默处理，不中断主流程
        return

    # 回填 downloadUrl
    for cf_idx, val_idx, entry, resource_id in file_entries:
        detail = file_details.get(resource_id)
        if detail and detail.get("downloadUrl"):
            entry["downloadUrl"] = detail["downloadUrl"]

def get_priority_label_map(project_id: str) -> Dict[int, str]:
    """
    获取企业优先级名称映射。
    直接查询企业优先级配置，失败时静默返回默认映射，不中断主流程。
    """
    # 检查缓存
    if project_id in _priority_label_cache:
        return _priority_label_cache[project_id]

    try:
        # 获取企业优先级配置（无需传参）
        resp = call_api.get("v3/project/priority/list")
        priorities = resp.get("result", [])
        if priorities:
            label_map = {int(p["priority"]): p["name"] for p in priorities if "priority" in p and "name" in p}
            _priority_label_cache[project_id] = label_map
            return label_map
    except Exception:
        # 查询失败时静默处理，使用默认值
        pass

    return DEFAULT_PRIORITY_LABEL

# 缓存项目自定义字段配置，避免重复请求
_custom_field_cache: Dict[str, Dict[str, str]] = {}

def enrich_custom_field_names(task: Dict[str, Any]) -> None:
    """
    为自定义字段补齐字段名称（cfName）。
    根据 projectId 获取项目自定义字段配置，构建 cfId -> name 映射。
    """
    customfields = task.get("customfields", [])
    if not customfields:
        return

    project_id = task.get("projectId")
    if not project_id:
        return

    # 检查缓存
    if project_id not in _custom_field_cache:
        try:
            resp = call_api.get(
                f"v3/project/{project_id}/customfield/search")
            fields = resp.get("result", [])
            # 构建 cfId -> name 映射（尝试 id 和 _id 两个字段）
            _custom_field_cache[project_id] = {}
            for f in fields:
                cf_id = f.get("id") or f.get("_id")
                if cf_id:
                    _custom_field_cache[project_id][cf_id] = f.get("name")
        except Exception:
            # 查询失败时静默处理，不中断主流程
            return

    name_map = _custom_field_cache.get(project_id, {})
    if not name_map:
        return

    # 为每个自定义字段添加 cfName
    for cf in customfields:
        cf_id = cf.get("cfId")
        if cf_id and cf_id in name_map:
            cf["cfName"] = name_map[cf_id]

def query_tasks(
    tql: Optional[str] = None,
    page_size: Optional[int] = 50,
    page_token: Optional[str] = None,
    fetch_details: bool = True,
    extra_fields: Optional[List[str]] = None,
) -> None:
    # Step 1: 查询任务 ID 列表
    params: Dict[str, Any] = {}
    if tql:
        params["tql"] = tql
    if page_size:
        params["pageSize"] = page_size
    else:
        params["pageSize"] = 50
    if page_token:
        params["pageToken"] = page_token

    data = call_api.get("v2/all-task/search", params=params)
    task_ids: List[str] = data.get("result", [])
    next_page_token = data.get("nextPageToken")
    total = data.get("count", len(task_ids))

    print(f"共找到 {total} 个任务，本页 {len(task_ids)} 个。", file=sys.stderr)

    if not task_ids:
        print(json.dumps([], ensure_ascii=False, indent=2))
        return

    if not fetch_details:
        print(json.dumps(task_ids, ensure_ascii=False, indent=2))
        if next_page_token:
            print(f"nextPageToken: {next_page_token}", file=sys.stderr)
        return

    # Step 2: 批量查询详情
    ids_str = ",".join(task_ids)
    detail_params: Dict[str, Any] = {"taskId": ids_str}
    # 合并默认字段和用户指定的额外字段
    fields = list(set(DEFAULT_EXTRA_FIELDS + (extra_fields or [])))
    detail_params["fields"] = ",".join(fields)
    detail_data = call_api.get("v3/task/query", params=detail_params)
    tasks: List[Dict[str, Any]] = detail_data.get("result", [])

    # 格式化输出：优先级转中文（自动获取企业配置），同时补齐文件下载链接和自定义字段名称
    for t in tasks:
        p = t.get("priority")
        if p is not None:
            project_id = t.get("projectId", "")
            label_map = get_priority_label_map(project_id) if project_id else DEFAULT_PRIORITY_LABEL
            t["priorityLabel"] = label_map.get(p, str(p))
        # 为文件类型的自定义字段补齐下载链接
        enrich_file_custom_fields(t)
        # 为自定义字段补齐字段名称
        enrich_custom_field_names(t)

    output = {
        "tasks": tasks,
        "count": len(tasks),
        "total": total,
    }
    if next_page_token:
        output["nextPageToken"] = next_page_token

    print(json.dumps(output, ensure_ascii=False, indent=2))

def main() -> None:
    if "--help" in sys.argv:
        print("""用法: uv run scripts/query_tasks.py [选项]

选项:
  --tql <TQL>              任务查询语言（可选）
  --page-size <N>          每页大小（可选）
  --page-token <T>         分页令牌（可选）
  --no-details             只返回任务 ID 列表，不查询详情
  --extra-fields <字段>    额外获取的字段，逗号分隔（如 sprintId,content）
                           注：note 字段默认已包含，无需额外指定
  --help                   显示帮助

TQL 常用示例:
  "executorId = me() AND isDone = false"                    我的待办任务
  "executorId = me() AND isDone = false AND dueDate < startOf(d)"  我的逾期任务
  "dueDate >= startOf(w) AND dueDate <= endOf(w)"           本周截止
  "dueDate >= startOf(d) AND dueDate <= endOf(d)"           今天截止
  "title ~ '关键词'"                                         标题模糊搜索
  "projectId = 'xxx'"                                       指定项目

完整 TQL 语法: references/tql.md""")
        sys.exit(0)

    tql = None
    page_size = None
    page_token = None
    fetch_details = True
    extra_fields: Optional[List[str]] = None

    i = 1
    while i < len(sys.argv):
        arg = sys.argv[i]
        if arg == "--tql" and i + 1 < len(sys.argv):
            tql = sys.argv[i + 1]; i += 2
        elif arg == "--page-size" and i + 1 < len(sys.argv):
            page_size = int(sys.argv[i + 1]); i += 2
        elif arg == "--page-token" and i + 1 < len(sys.argv):
            page_token = sys.argv[i + 1]; i += 2
        elif arg == "--no-details":
            fetch_details = False; i += 1
        elif arg == "--extra-fields" and i + 1 < len(sys.argv):
            extra_fields = [f.strip() for f in sys.argv[i + 1].split(",")]; i += 2
        else:
            print(f"❌ 未知参数: {arg}，使用 --help 查看帮助", file=sys.stderr)
            sys.exit(1)

    query_tasks(tql, page_size, page_token, fetch_details, extra_fields)

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
更新 Teambition 任务（多字段并行更新）
用法: uv run scripts/update_task.py --task-id <ID> [字段选项...]

优先级: 0=紧急 1=高 2=中 3=低
日期: 传入东八区时间，脚本自动转换为 UTC
"""

import json
import sys
from concurrent.futures import ThreadPoolExecutor, as_completed
from datetime import datetime, timezone, timedelta
from typing import Any, Dict, List, Optional, Tuple

import call_api

CST = timezone(timedelta(hours=8))


def cst_to_utc(dt_str: str) -> str:
    if dt_str.endswith("Z") or "+00:00" in dt_str:
        return dt_str
    for fmt in ("%Y-%m-%dT%H:%M:%S.%f", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d"):
        try:
            dt = datetime.strptime(dt_str, fmt).replace(tzinfo=CST)
            return dt.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.000Z")
        except ValueError:
            continue
    return dt_str


def _do_update(label: str, method: str, path: str, body: Dict[str, Any]) -> Tuple[str, bool]:
    try:
        if method == "PUT":
            call_api.put(path, body)
        else:
            call_api.post(path, body)
        return label, True
    except SystemExit:
        return label, False


def update_task(task_id: str, updates: Dict[str, Any]) -> bool:
    """并行执行所有字段更新，返回是否全部成功。"""
    jobs: List[Tuple[str, str, str, Dict[str, Any]]] = []

    if "content" in updates:
        jobs.append(("标题", "PUT", f"v3/task/{task_id}/content", {"content": updates["content"]}))
    if "executorId" in updates:
        jobs.append(("执行人", "PUT", f"v3/task/{task_id}/executor", {"executorId": updates["executorId"]}))
    if "dueDate" in updates:
        jobs.append(("截止日期", "PUT", f"v3/task/{task_id}/dueDate", {"dueDate": updates["dueDate"]}))
    if "startDate" in updates:
        jobs.append(("开始日期", "PUT", f"v3/task/{task_id}/startDate", {"startDate": updates["startDate"]}))
    if "note" in updates:
        jobs.append(("备注", "PUT", f"v3/task/{task_id}/note", {"note": updates["note"]}))
    if "priority" in updates:
        jobs.append(("优先级", "PUT", f"v3/task/{task_id}/priority", {"priority": updates["priority"]}))
    if "storyPoint" in updates:
        jobs.append(("故事点", "PUT", f"v3/task/{task_id}/storyPoint", {"storyPoint": updates["storyPoint"]}))
    if "taskflowstatusId" in updates:
        jobs.append(("任务状态", "PUT", f"v3/task/{task_id}/taskflowstatus", {"taskflowstatusId": updates["taskflowstatusId"]}))

    # 参与者（involveMembers / addInvolvers / delInvolvers）
    involver_payload: Dict[str, Any] = {}
    if "involveMembers" in updates:
        involver_payload["involveMembers"] = updates["involveMembers"]
    if "addInvolvers" in updates:
        involver_payload["addInvolvers"] = updates["addInvolvers"]
    if "delInvolvers" in updates:
        involver_payload["delInvolvers"] = updates["delInvolvers"]
    if involver_payload:
        jobs.append(("参与者", "PUT", f"v3/task/{task_id}/involveMembers", involver_payload))

    # 自定义字段（每个字段单独调用 POST）
    for idx, cf in enumerate(updates.get("customfields", [])):
        jobs.append((f"自定义字段#{idx+1}", "POST", f"v3/task/{task_id}/customfield/update", cf))

    if not jobs:
        print("❌ 未指定任何要更新的字段", file=sys.stderr)
        return False

    print(f"并行更新 {len(jobs)} 个字段...", file=sys.stderr)
    results: List[Tuple[str, bool]] = []

    with ThreadPoolExecutor(max_workers=min(len(jobs), 10)) as executor:
        futures = {executor.submit(_do_update, label, method, path, body): label
                   for label, method, path, body in jobs}
        for future in as_completed(futures):
            label, ok = future.result()
            results.append((label, ok))
            status = "✅" if ok else "❌"
            print(f"  {status} {label}", file=sys.stderr)

    success_count = sum(1 for _, ok in results if ok)
    print(f"完成: {success_count}/{len(jobs)} 成功", file=sys.stderr)
    return success_count == len(jobs)


def main() -> None:
    if "--help" in sys.argv:
        print("""用法: uv run scripts/update_task.py --task-id <ID> [字段选项...]

必需:
  --task-id <ID>                任务 ID

可更新字段:
  --title <标题>                任务标题
  --executor-id <ID>            执行人 ID
  --due-date <日期>             截止日期（东八区，自动转 UTC）
  --start-date <日期>           开始日期（东八区，自动转 UTC）
  --note <备注>                 任务备注
  --priority <0-3>              优先级（0=紧急 1=高 2=中 3=低）
  --story-point <点数>          故事点
  --taskflowstatus-id <ID>      任务状态 ID
  --involve-members <JSON>      参与者列表（完全替换）
  --add-involvers <JSON>        新增参与者
  --del-involvers <JSON>        移除参与者
  --customfields <JSON>         自定义字段数组（使用 customfieldId 而非 cfId）
  --help                        显示帮助

示例:
  uv run scripts/update_task.py --task-id 'xxx' --content '新标题' --priority 0
  uv run scripts/update_task.py --task-id 'xxx' --due-date '2026-04-01' --executor-id 'uid'""")
        sys.exit(0)

    task_id: Optional[str] = None
    updates: Dict[str, Any] = {}

    i = 1
    while i < len(sys.argv):
        arg = sys.argv[i]
        if arg == "--task-id" and i + 1 < len(sys.argv):
            task_id = sys.argv[i + 1]; i += 2
        elif arg == "--title" and i + 1 < len(sys.argv):
            updates["content"] = sys.argv[i + 1]; i += 2
        elif arg == "--executor-id" and i + 1 < len(sys.argv):
            updates["executorId"] = sys.argv[i + 1]; i += 2
        elif arg == "--due-date" and i + 1 < len(sys.argv):
            updates["dueDate"] = cst_to_utc(sys.argv[i + 1]); i += 2
        elif arg == "--start-date" and i + 1 < len(sys.argv):
            updates["startDate"] = cst_to_utc(sys.argv[i + 1]); i += 2
        elif arg == "--note" and i + 1 < len(sys.argv):
            updates["note"] = sys.argv[i + 1]; i += 2
        elif arg == "--priority" and i + 1 < len(sys.argv):
            updates["priority"] = int(sys.argv[i + 1]); i += 2
        elif arg == "--story-point" and i + 1 < len(sys.argv):
            updates["storyPoint"] = sys.argv[i + 1]; i += 2
        elif arg == "--taskflowstatus-id" and i + 1 < len(sys.argv):
            updates["taskflowstatusId"] = sys.argv[i + 1]; i += 2
        elif arg == "--involve-members" and i + 1 < len(sys.argv):
            updates["involveMembers"] = json.loads(sys.argv[i + 1]); i += 2
        elif arg == "--add-involvers" and i + 1 < len(sys.argv):
            updates["addInvolvers"] = json.loads(sys.argv[i + 1]); i += 2
        elif arg == "--del-involvers" and i + 1 < len(sys.argv):
            updates["delInvolvers"] = json.loads(sys.argv[i + 1]); i += 2
        elif arg == "--customfields" and i + 1 < len(sys.argv):
            updates["customfields"] = json.loads(sys.argv[i + 1]); i += 2
        else:
            print(f"❌ 未知参数: {arg}", file=sys.stderr); sys.exit(1)

    if not task_id:
        print("❌ 缺少 --task-id", file=sys.stderr); sys.exit(1)

    ok = update_task(task_id, updates)
    sys.exit(0 if ok else 1)


if __name__ == "__main__":
    main()
